def formula(n1, theta1, n2):
    # theta1 in radians
    # Clamp argument to [-1, 1] to avoid arcsin domain errors (total internal reflection)
    sin_theta2 = (n1 / n2) * np.sin(theta1)
    sin_theta2_clamped = np.maximum(-1.0, np.minimum(1.0, sin_theta2))
    return np.arcsin(sin_theta2_clamped)

